// ============================================================
// BUILD PROMPTS
// Turns the form input into up to 18 buyer-intent questions.
// EDITABLE: the question templates below, the service cap
// (.slice(0, 4)) and the total cap (.slice(0, 18)).
// Keep templates IDENTICAL month-to-month per client so
// visibility scores stay comparable.
// ============================================================
const form = $input.first().json;
const business = (form['Business Name'] || '').trim();
const town = (form['Town / City'] || '').trim();
const county = (form['County / Wider Area'] || '').trim();
const services = (form['Services (comma separated)'] || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean)
  .slice(0, 4); // cap at 4 services to control cost

const prompts = [];

// --- Buyer-intent prompts per service (edit wording freely) ---
for (const service of services) {
  prompts.push({ prompt: `Who is the best ${service} in ${town}?`, category: 'buyer-intent' });
  prompts.push({ prompt: `I need a ${service} in ${town}. Who do you recommend and why?`, category: 'buyer-intent' });
  prompts.push({ prompt: `Recommend a reliable, well-reviewed ${service} near ${town}.`, category: 'buyer-intent' });
}

// --- Wider-area prompt ---
if (county && services.length > 0) {
  prompts.push({ prompt: `Best ${services[0]} in ${county}?`, category: 'buyer-intent-wide' });
}

// --- Brand-reputation prompts ---
prompts.push({ prompt: `Is ${business} in ${town} any good? What do people say about them?`, category: 'brand' });
prompts.push({ prompt: `Tell me about ${business}, ${town}. What services do they offer and are they reputable?`, category: 'brand' });

// --- Cap total prompts ---
const capped = prompts.slice(0, 18);

return capped.map((p, i) => ({
  json: {
    index: i,
    prompt: p.prompt,
    category: p.category,
    business,
    town
  }
}));

// Extracts the plain-text answer from Claude's response
// and re-attaches the original prompt. No changes needed.
const src = $('Build Prompts').item.json;
const blocks = $json.content || [];
const answer = blocks
  .filter(b => b.type === 'text')
  .map(b => b.text)
  .join('\n')
  .trim();

return {
  json: {
    index: src.index,
    prompt: src.prompt,
    category: src.category,
    claude_answer: answer || '(no answer returned)'
  }
};

// Extracts the plain-text answer from Perplexity's response.
// No changes needed.
const src = $('Build Prompts').item.json;
const answer = ($json.choices && $json.choices[0] && $json.choices[0].message)
  ? $json.choices[0].message.content
  : '';

return {
  json: {
    index: src.index,
    perplexity_answer: (answer || '(no answer returned)').trim()
  }
};

// Extracts the plain-text answer from OpenAI's Responses API
// output. No changes needed.
const src = $('Build Prompts').item.json;
const out = $json.output || [];
let answer = '';
for (const o of out) {
  if (o.type === 'message' && Array.isArray(o.content)) {
    answer += o.content
      .filter(c => c.type === 'output_text')
      .map(c => c.text)
      .join('\n');
  }
}

return {
  json: {
    index: src.index,
    chatgpt_answer: (answer || '(no answer returned)').trim()
  }
};

// ============================================================
// AGGREGATE RESULTS
// Parses each analysis, computes visibility scores per engine,
// and ranks the competitors AI recommends instead.
// No changes needed.
// ============================================================
const analyses = $input.all();
const merged = $('Merge Answers').all();
const form = $('Audit Request Form').first().json;

const rows = [];
let claudeMentions = 0;
let pplxMentions = 0;
let gptMentions = 0;
const competitorCount = {};

for (let i = 0; i < analyses.length; i++) {
  const resp = analyses[i].json;
  const blocks = resp.content || [];
  let text = blocks.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
  text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

  let a = null;
  try { a = JSON.parse(text); } catch (e) { a = null; }

  const src = merged[i] ? merged[i].json : {};

  if (a) {
    if (a.claude && a.claude.mentioned) claudeMentions++;
    if (a.perplexity && a.perplexity.mentioned) pplxMentions++;
    if (a.chatgpt && a.chatgpt.mentioned) gptMentions++;
    const comps = []
      .concat((a.claude && a.claude.competitors_mentioned) || [])
      .concat((a.perplexity && a.perplexity.competitors_mentioned) || [])
      .concat((a.chatgpt && a.chatgpt.competitors_mentioned) || []);
    for (const c of comps) {
      const k = String(c).trim();
      if (k) competitorCount[k] = (competitorCount[k] || 0) + 1;
    }
  }

  rows.push({
    prompt: src.prompt || '(unknown prompt)',
    category: src.category || '',
    analysis: a
  });
}

const total = analyses.length;
const topCompetitors = Object.entries(competitorCount)
  .sort((x, y) => y[1] - x[1])
  .slice(0, 8)
  .map(([name, count]) => ({ name, count }));

return [{
  json: {
    business: form['Business Name'],
    town: form['Town / City'],
    audit_date: new Date().toISOString().slice(0, 10),
    total_prompts: total,
    claude_mentions: claudeMentions,
    perplexity_mentions: pplxMentions,
    chatgpt_mentions: gptMentions,
    claude_visibility_rate: total ? Math.round((100 * claudeMentions) / total) : 0,
    perplexity_visibility_rate: total ? Math.round((100 * pplxMentions) / total) : 0,
    chatgpt_visibility_rate: total ? Math.round((100 * gptMentions) / total) : 0,
    top_competitors: topCompetitors,
    rows
  }
}];

// Pulls the HTML out of Claude's response and prepares the
// email fields. No changes needed.
const blocks = $json.content || [];
let html = blocks.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
html = html.replace(/^```html\s*/i, '').replace(/```\s*$/,'').trim();

const form = $('Audit Request Form').first().json;

return {
  json: {
    html,
    subject: 'AI Visibility Audit — ' + form['Business Name'] + ' (' + form['Town / City'] + ')',
    to: form['Report Recipient Email']
  }
};
